CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_post(p_post_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if not exists (
    select 1
    from public.posts
    where id = p_post_id
      and user_id = auth.uid()
  ) then
    raise exception 'You can only delete your own post';
  end if;

  delete from public.post_likes where post_id = p_post_id;
  delete from public.comment_likes
    where comment_id in (
      select id from public.comments where post_id = p_post_id
    );
  delete from public.comments where post_id = p_post_id;
  delete from public.reposts where post_id = p_post_id;
  delete from public.bookmarks where post_id = p_post_id;
  delete from public.shares where post_id = p_post_id;
  delete from public.post_views where post_id = p_post_id;
  delete from public.posts
    where id = p_post_id
      and user_id = auth.uid();
end;
$function$

CREATE OR REPLACE FUNCTION public.restore_post(p_post_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM posts WHERE id = p_post_id AND user_id = auth.uid() AND is_deleted = true) THEN
    RAISE EXCEPTION 'Post not found or not deleted';
  END IF;
  UPDATE posts SET is_deleted = false, deleted_at = NULL WHERE id = p_post_id;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_original_sound_for_post(p_post_id uuid, p_audio_url text, p_art_url text DEFAULT NULL::text, p_title text DEFAULT NULL::text)
 RETURNS sounds
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_post public.posts%rowtype;
  v_sound public.sounds%rowtype;
  v_profile public.profiles%rowtype;
  v_title text;
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  if p_post_id is null or nullif(trim(p_audio_url), '') is null then
    raise exception 'Post ID and audio URL are required';
  end if;

  select *
  into v_post
  from public.posts
  where id = p_post_id
    and user_id = v_user_id
    and media_type = 'video';

  if not found then
    raise exception 'Video post not found or not owned by current user';
  end if;

  if v_post.sound_id is not null then
    select * into v_sound from public.sounds where id = v_post.sound_id;
    if found then return v_sound; end if;
  end if;

  select *
  into v_sound
  from public.sounds
  where source_post_id = p_post_id
  limit 1;

  if found then
    update public.posts
    set sound_id = v_sound.id
    where id = p_post_id and user_id = v_user_id;
    return v_sound;
  end if;

  select * into v_profile
  from public.profiles
  where id = v_user_id;

  v_title := coalesce(
    nullif(trim(p_title), ''),
    'Original sound · ' ||
    coalesce(
      nullif(v_profile.display_name, ''),
      nullif(v_profile.username, ''),
      'FreeUpper user'
    )
  );

  insert into public.sounds (
    title,
    artist_name,
    audio_url,
    art_url,
    created_by,
    source_post_id,
    sound_type,
    is_original,
    status,
    usage_count
  )
  values (
    v_title,
    coalesce(
      nullif(v_profile.display_name, ''),
      nullif(v_profile.username, ''),
      'FreeUpper user'
    ),
    p_audio_url,
    p_art_url,
    v_user_id,
    p_post_id,
    'original',
    true,
    'active',
    1
  )
  returning * into v_sound;

  update public.posts
  set sound_id = v_sound.id
  where id = p_post_id and user_id = v_user_id;

  return v_sound;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_post_likes_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.posts SET likes_count = likes_count + 1 WHERE id = NEW.post_id;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.posts SET likes_count = likes_count - 1 WHERE id = OLD.post_id;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_user_settings()
 RETURNS user_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  settings user_settings;
BEGIN
  SELECT * INTO settings FROM user_settings WHERE user_id = auth.uid();
  IF settings IS NULL THEN
    INSERT INTO user_settings (user_id) VALUES (auth.uid()) RETURNING * INTO settings;
  END IF;
  RETURN settings;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_sound_usage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  old_sound text;
  new_sound text;
  old_post text;
  new_post text;
  inserted_count integer;
begin
  if tg_op = 'INSERT' then
    new_sound := nullif(to_jsonb(new)->>'sound_id', '');
    new_post := to_jsonb(new)->>'id';

    if new_sound is not null and new_post is not null then
      insert into public.sound_usage (sound_id, post_id)
      values (new_sound, new_post)
      on conflict (sound_id, post_id) do nothing;

      get diagnostics inserted_count = row_count;

      if inserted_count > 0 then
        update public.sounds
        set usage_count = coalesce(usage_count, 0) + 1
        where id = new_sound;
      end if;
    end if;

    return new;

  elsif tg_op = 'DELETE' then
    old_sound := nullif(to_jsonb(old)->>'sound_id', '');
    old_post := to_jsonb(old)->>'id';

    if old_sound is not null and old_post is not null then
      delete from public.sound_usage
      where sound_id = old_sound
        and post_id = old_post;

      get diagnostics inserted_count = row_count;

      if inserted_count > 0 then
        update public.sounds
        set usage_count = greatest(coalesce(usage_count, 0) - 1, 0)
        where id = old_sound;
      end if;
    end if;

    return old;

  elsif tg_op = 'UPDATE' then
    old_sound := nullif(to_jsonb(old)->>'sound_id', '');
    new_sound := nullif(to_jsonb(new)->>'sound_id', '');
    old_post := to_jsonb(old)->>'id';
    new_post := to_jsonb(new)->>'id';

    if old_sound is not distinct from new_sound then
      return new;
    end if;

    if old_sound is not null and old_post is not null then
      delete from public.sound_usage
      where sound_id = old_sound
        and post_id = old_post;

      get diagnostics inserted_count = row_count;

      if inserted_count > 0 then
        update public.sounds
        set usage_count = greatest(coalesce(usage_count, 0) - 1, 0)
        where id = old_sound;
      end if;
    end if;

    if new_sound is not null and new_post is not null then
      insert into public.sound_usage (sound_id, post_id)
      values (new_sound, new_post)
      on conflict (sound_id, post_id) do nothing;

      get diagnostics inserted_count = row_count;

      if inserted_count > 0 then
        update public.sounds
        set usage_count = coalesce(usage_count, 0) + 1
        where id = new_sound;
      end if;
    end if;

    return new;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.toggle_bookmark(p_post_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  exists_bookmark BOOLEAN;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  SELECT EXISTS(SELECT 1 FROM bookmarks WHERE post_id = p_post_id AND user_id = v_user_id)
  INTO exists_bookmark;
  IF exists_bookmark THEN
    DELETE FROM bookmarks WHERE post_id = p_post_id AND user_id = v_user_id;
  ELSE
    INSERT INTO bookmarks (post_id, user_id) VALUES (p_post_id, v_user_id);
  END IF;
  RETURN NOT exists_bookmark;
END;
$function$

CREATE OR REPLACE FUNCTION public.edit_comment(p_comment_id uuid, p_message text)
 RETURNS comments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  updated_comment comments;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM comments WHERE id = p_comment_id AND user_id = auth.uid() AND is_deleted = false) THEN
    RAISE EXCEPTION 'Comment not found or not owned';
  END IF;
  IF p_message IS NULL OR trim(p_message) = '' THEN
    RAISE EXCEPTION 'Message cannot be empty';
  END IF;
  UPDATE comments
  SET
    message = p_message,
    edited_at = now(),
    version = version + 1
  WHERE id = p_comment_id
  RETURNING * INTO updated_comment;
  RETURN updated_comment;
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_post_like()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_post_owner UUID;
BEGIN
  SELECT user_id INTO v_post_owner
  FROM posts
  WHERE id = NEW.post_id;

  IF v_post_owner IS NULL THEN
    RETURN NEW;
  END IF;

  IF v_post_owner = NEW.user_id THEN
    RETURN NEW;
  END IF;

  PERFORM create_notification(v_post_owner, NEW.user_id, 'like', NEW.post_id, NULL);

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.increment_view_count(post_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  UPDATE public.posts SET views = views + 1 WHERE id = post_id;
  INSERT INTO public.views (post_id, user_id) VALUES (post_id, auth.uid());
END;
$function$

CREATE OR REPLACE FUNCTION public.toggle_like(p_post_id bigint, p_user_id uuid)
 RETURNS TABLE(liked boolean, count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  existing_like RECORD;
BEGIN
  SELECT * INTO existing_like FROM public.post_likes 
  WHERE post_id = p_post_id AND user_id = p_user_id;

  IF existing_like IS NOT NULL THEN
    DELETE FROM public.post_likes WHERE post_id = p_post_id AND user_id = p_user_id;
    liked := false;
  ELSE
    INSERT INTO public.post_likes (post_id, user_id) VALUES (p_post_id, p_user_id);
    liked := true;
  END IF;

  SELECT COUNT(*)::BIGINT INTO count FROM public.post_likes WHERE post_id = p_post_id;
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_comment_like()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_comment_author UUID;
BEGIN
  SELECT user_id
  INTO v_comment_author
  FROM comments
  WHERE id = NEW.comment_id;

  IF v_comment_author IS NULL THEN
    RETURN NEW;
  END IF;

  IF v_comment_author = NEW.user_id THEN
